<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Bouncing Ball Playground</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0a0d16;
      --panel: #141a29;
      --line: #29334a;
      --text: #eaf1ff;
      --muted: #9aa8c2;
      --accent: #7a9cff;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      background:
        radial-gradient(circle at 50% 15%, #1b2441 0%, transparent 42%),
        var(--bg);
      color: var(--text);
      font-family: system-ui, sans-serif;
    }

    main {
      width: min(92vw, 780px);
      text-align: center;
    }

    h1 {
      margin: 0 0 8px;
      font-size: clamp(1.35rem, 3vw, 2rem);
      letter-spacing: 0.04em;
    }

    p {
      margin: 0 0 18px;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .canvas-wrap {
      border: 1px solid var(--line);
      border-radius: 18px;
      overflow: hidden;
      background: #0d1220;
      box-shadow: 0 22px 60px rgba(0, 0, 0, 0.45);
    }

    canvas {
      display: block;
      width: 720px;
      height: 500px;
      max-width: 100%;
      cursor: crosshair;
      touch-action: none;
      background:
        linear-gradient(rgba(255,255,255,0.025) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255,255,255,0.025) 1px, transparent 1px),
        #0d1220;
      background-size: 28px 28px;
    }

    .controls {
      display: flex;
      justify-content: center;
      flex-wrap: wrap;
      gap: 10px;
      margin-top: 16px;
    }

    button {
      appearance: none;
      border: 1px solid #3c4a70;
      border-radius: 10px;
      padding: 10px 17px;
      color: var(--text);
      background: var(--panel);
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: transform 120ms ease, background 120ms ease, border-color 120ms ease;
    }

    button:hover {
      transform: translateY(-2px);
      background: #202a43;
      border-color: var(--accent);
    }

    button:active { transform: translateY(0); }

    #drop {
      background: linear-gradient(135deg, #566ff0, #8e64e9);
      border-color: #8296ff;
    }
  </style>
</head>
<body>
  <main>
    <h1>Bouncing Ball Playground</h1>
    <p>Click anywhere in the arena to drop a ball.</p>

    <div class="canvas-wrap">
      <canvas id="sim" width="720" height="500" aria-label="Bouncing ball simulation"></canvas>
    </div>

    <div class="controls">
      <button id="drop" type="button">Drop ball</button>
      <button id="play" type="button">Pause</button>
      <button id="clear" type="button">Clear</button>
    </div>
  </main>

  <script>
    (() => {
      const canvas = document.getElementById("sim");
      const ctx = canvas.getContext("2d");
      const dropButton = document.getElementById("drop");
      const playButton = document.getElementById("play");
      const clearButton = document.getElementById("clear");

      const w = canvas.width;
      const h = canvas.height;
      const gravity = 0.42;
      const restitution = 0.82;
      const balls = [];
      let playing = true;
      let lastTime = performance.now();

      const palette = [
        ["#7a9cff", "#c0ccff"],
        ["#f778a1", "#ffc3d6"],
        ["#63dbba", "#b9ffe9"],
        ["#f5b95c", "#ffe1a5"],
        ["#b882f3", "#e4c6ff"]
      ];

      function number(value, fallback) {
        return Number.isFinite(Number(value)) ? Number(value) : fallback;
      }

      function addBall(x, y, vx = 0, vy = 0, r = 15) {
        r = Math.max(3, Math.min(number(r, 15), Math.min(w, h) / 2));
        const ball = {
          x: Math.max(r, Math.min(w - r, number(x, w / 2))),
          y: Math.max(r, Math.min(h - r, number(y, h / 4))),
          vx: number(vx, 0),
          vy: number(vy, 0),
          r,
          color: palette[balls.length % palette.length]
        };
        balls.push(ball);
        draw();
        return { x: ball.x, y: ball.y, vx: ball.vx, vy: ball.vy, r: ball.r };
      }

      function clear() {
        balls.length = 0;
        draw();
      }

      function collideWithEdges(ball) {
        if (ball.x - ball.r < 0) {
          ball.x = ball.r;
          if (ball.vx < 0) ball.vx = -ball.vx * restitution;
        } else if (ball.x + ball.r > w) {
          ball.x = w - ball.r;
          if (ball.vx > 0) ball.vx = -ball.vx * restitution;
        }

        if (ball.y - ball.r < 0) {
          ball.y = ball.r;
          if (ball.vy < 0) ball.vy = -ball.vy * restitution;
        } else if (ball.y + ball.r > h) {
          ball.y = h - ball.r;
          if (ball.vy > 0) ball.vy = -ball.vy * restitution;
        }
      }

      function step(dt = 1) {
        dt = Math.max(0, number(dt, 1));

        for (const ball of balls) {
          ball.vy += gravity * dt;
          ball.x += ball.vx * dt;
          ball.y += ball.vy * dt;

          // Clamping after every update guarantees no ball can leave the canvas.
          collideWithEdges(ball);
        }

        draw();
      }

      function draw() {
        ctx.clearRect(0, 0, w, h);

        const floorGlow = ctx.createLinearGradient(0, h - 90, 0, h);
        floorGlow.addColorStop(0, "rgba(103, 137, 255, 0)");
        floorGlow.addColorStop(1, "rgba(103, 137, 255, 0.10)");
        ctx.fillStyle = floorGlow;
        ctx.fillRect(0, h - 90, w, 90);

        for (const ball of balls) {
          const [base, shine] = ball.color;

          ctx.beginPath();
          ctx.ellipse(ball.x, h - ball.r * 0.36, ball.r * 0.82, ball.r * 0.19, 0, 0, Math.PI * 2);
          ctx.fillStyle = "rgba(0, 0, 0, 0.24)";
          ctx.fill();

          const gradient = ctx.createRadialGradient(
            ball.x - ball.r * 0.32, ball.y - ball.r * 0.38, ball.r * 0.08,
            ball.x, ball.y, ball.r
          );
          gradient.addColorStop(0, shine);
          gradient.addColorStop(0.32, base);
          gradient.addColorStop(1, "#202a55");

          ctx.beginPath();
          ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
          ctx.fillStyle = gradient;
          ctx.fill();
          ctx.lineWidth = 1.3;
          ctx.strokeStyle = "rgba(255,255,255,0.38)";
          ctx.stroke();

          ctx.beginPath();
          ctx.arc(ball.x - ball.r * 0.3, ball.y - ball.r * 0.34, ball.r * 0.18, 0, Math.PI * 2);
          ctx.fillStyle = "rgba(255,255,255,0.55)";
          ctx.fill();
        }
      }

      function animate(time) {
        const elapsed = Math.min(40, time - lastTime);
        lastTime = time;
        if (playing) step(elapsed / (1000 / 60));
        requestAnimationFrame(animate);
      }

      canvas.addEventListener("pointerdown", event => {
        const rect = canvas.getBoundingClientRect();
        const x = (event.clientX - rect.left) * w / rect.width;
        const y = (event.clientY - rect.top) * h / rect.height;
        addBall(x, y, (Math.random() - 0.5) * 4, -1 - Math.random() * 3, 12 + Math.random() * 8);
      });

      dropButton.addEventListener("click", () => {
        addBall(
          w * (0.25 + Math.random() * 0.5),
          55,
          (Math.random() - 0.5) * 5,
          0,
          12 + Math.random() * 9
        );
      });

      playButton.addEventListener("click", () => {
        playing = !playing;
        playButton.textContent = playing ? "Pause" : "Play";
        lastTime = performance.now();
      });

      clearButton.addEventListener("click", clear);

      window.sim = {
        w,
        h,
        balls: () => balls.map(ball => ({
          x: ball.x,
          y: ball.y,
          vx: ball.vx,
          vy: ball.vy,
          r: ball.r
        })),
        addBall,
        clear,
        step
      };

      addBall(w * 0.5, 80, 2.2, 0, 18);
      draw();
      requestAnimationFrame(animate);
    })();
  </script>
</body>
</html>
